// Creates a new DateRangePreset with a date and time, or a range of them.
//
// Times are kept as given, even though a range picker edits dates only.
//
// NewDateRangePresetDateTime calls <gpui_kit::component::date_picker::DateRangePreset>::date_time.
func NewDateRangePresetDateTime(label string, value DateTime) DateRangePreset {
	n := rt.NewValue(836)
	o := rt.NodeArgs(n)
	o.Str(label)
	putDateTime(o, value)
	return DateRangePreset{Val: rt.MkVal(n)}
}

